mapper.update:
UPDATE TB_TIP
SET thumbnail_img = #{thumbnailImg},
    updated_at = NOW()

WHERE tip_id = #{tipId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'

mapper.select:
SELECT t.*, u.nickname AS nickname, u.profile_img AS profileImg,
	(
		SELECT COUNT(*) FROM TB_TIP_LIKE tl WHERE tl.tip_id = t.tip_id
	) AS like_count,

	(
		SELECT COUNT(*) FROM TB_TIP_COMMENT tc WHERE tc.tip_id = t.tip_id AND tc.status = 'ACTIVE'
	) AS comment_count

FROM TB_TIP t LEFT JOIN TB_USER u ON t.user_id = u.user_id WHERE t.status = 'ACTIVE' AND t.visibility = 'PUBLIC'


	AND (

			t.country = #{countryKeyword}

	)




	AND (
		t.title LIKE CONCAT('%', #{keyword}, '%')
		OR t.content LIKE CONCAT('%', #{keyword}, '%')
		OR t.country LIKE CONCAT('%', #{keyword}, '%')
		OR t.city LIKE CONCAT('%', #{keyword}, '%')
		OR t.hashtag LIKE CONCAT('%', #{keyword}, '%')
	)




		ORDER BY t.view_count DESC, t.created_at DESC



		ORDER BY like_count DESC, t.created_at DESC



		ORDER BY t.created_at DESC


LIMIT #{pageSize}
OFFSET #{offset}

SELECT COUNT(*) FROM TB_TIP t WHERE t.status = 'ACTIVE' AND t.visibility = 'PUBLIC'
AND (
t.country = #{countryKeyword}
)
AND ( t.title LIKE CONCAT('%', #{keyword}, '%') OR t.content LIKE CONCAT('%', #{keyword}, '%') OR t.country LIKE CONCAT('%', #{keyword}, '%') OR t.city LIKE CONCAT('%', #{keyword}, '%') OR t.hashtag LIKE CONCAT('%', #{keyword}, '%') )
